fn find_max(a: &[i32], n: usize) -> usize {
    // Ensure n is within bounds (though problem states it's guaranteed)
    let prefix = &a[..n];
    
    // Find the maximum value in the prefix
    let max_value = prefix.iter().max().unwrap();
    
    // Find the first index where this maximum value occurs
    prefix.iter().position(|&x| x == *max_value).unwrap()
}

// Alternative implementation that finds the index in a single pass:
fn find_max_single_pass(a: &[i32], n: usize) -> usize {
    let mut max_index = 0;
    let mut max_value = a[0];
    
    for i in 1..n {
        if a[i] > max_value {
            max_value = a[i];
            max_index = i;
        }
    }
    
    max_index
}

// The main implementation using the single-pass approach (more efficient)
fn findMax(a: &[i32], n: usize) -> usize {
    find_max_single_pass(a, n)
}